      'novel.optimize.preview': '优化稿：{paragraphs} 段 / {characters} 字',
      'novel.optimize.previewTruncated': '预览只显示前 200 段；应用前可先放弃并重试，或直接应用完整版本。',
      'novel.optimize.view': '查看优化稿',
