    function NovelEditForm({ novel, onClose, onSaved }) {
      const t = useTranslate()
      const [detail, setDetail] = useState(null)
      const [title, setTitle] = useState(novel.title || '')
      const [genre, setGenre] = useState('')
      const [budgets, setBudgets] = useState(null)
      const [writerMode, setWriterMode] = useState('inline')
      const [busy, setBusy] = useState(false)
      const [error, setError] = useState('')
      const [notice, setNotice] = useState('')
      const applyDetail = (next) => {
        setDetail(next)
        setTitle(typeof next?.title === 'string' ? next.title : novel.title || '')
        setGenre(typeof next?.config?.genre === 'string' ? next.config.genre : '')
        setBudgets(novelBudgetsToForm(next?.config?.budgets))
        setWriterMode(next?.config?.writerMode === 'subagent' ? 'subagent' : 'inline')
      }
      useEffect(() => {
        let cancelled = false
        void fetchNovelDetail(novel.novelId)
          .then((next) => { if (!cancelled) applyDetail(next) })
          .catch((cause) => { if (!cancelled) setError(cause instanceof Error ? cause.message : String(cause)) })
        return () => { cancelled = true }
      }, [novel.novelId])
      const setBudgetField = (key, value) => setBudgets((current) => ({ ...current, [key]: value }))
      const save = () => {
        if (busy || detail === null || budgets === null) return
        const patch = {}
        const nextTitle = title.trim()
        const nextGenre = genre.trim()
        if (nextTitle !== '' && nextTitle !== detail.title) patch.title = nextTitle
        if (nextGenre !== (detail.config?.genre ?? '')) patch.genre = nextGenre
        const parsed = novelFormToBudgets(budgets)
        if (NOVEL_BUDGET_FIELDS.some((field) => !field.optional && field.pick(parsed) === null)) {
          setError(t('novel.edit.invalidBudgets'))
          return
        }
        // 预算在 noteTurn 中从快照实时读取（§13），改完下一轮即生效；
        // 未改动的预算不下发，避免无意义的 revision 递增。
        if (novelBudgetsChanged(budgets, detail.config?.budgets)) {
          patch.budgets = parsed
        }
        // 写作模式（0007 §8）：与预算同走既有 PATCH 通道，仅在值变化时下发；
        // 切换只影响下一单元（服务端语义），面板只如实展示与提交。
        const nextWriterMode = writerMode === 'subagent' ? 'subagent' : 'inline'
        const currentWriterMode = detail.config?.writerMode === 'subagent' ? 'subagent' : 'inline'
        if (nextWriterMode !== currentWriterMode) {
          patch.writerMode = nextWriterMode
        }
        if (Object.keys(patch).length === 0) {
          onSaved()
          return
        }
        setBusy(true)
        setError('')
        setNotice('')
        void patchNovel(novel.novelId, detail.revision, patch)
          .then(() => onSaved())
          .catch((cause) => {
            if (isNovelConflict(cause)) {
              // CAS 冲突：自动重取详情并提示（契约要求），保留弹窗让用户重试。
              setNotice(t('novel.conflict'))
              void fetchNovelDetail(novel.novelId)
                .then((next) => applyDetail(next))
                .catch(() => {})
            } else {
              setError(cause instanceof Error ? cause.message : String(cause))
            }
          })
          .finally(() => setBusy(false))
      }
      return h(NovelModalFrame, {
        title: t('novel.editTitle'),
        closeLabel: t('panel.close'),
        onClose,
        footer: h(React.Fragment, null,
          h(Button, { size: 'sm', variant: 'ghost', onClick: onClose }, t('panel.cancel')),
          h(Button, { size: 'sm', variant: 'primary', disabled: busy || detail === null || title.trim() === '', onClick: save },
            busy ? t('settings.importing') : t('panel.save'))),
      },
      h('div', { className: 'dt-novel-form-grid' },
        h(EditorField, { label: t('novel.form.title'), value: title, onChange: setTitle }),
        h(EditorField, { label: t('novel.genre'), value: genre, onChange: setGenre })),
      h('div', { className: 'dt-novel-form-section' },
        h('h4', null, t('novel.form.budgets')),
        h('div', { className: 'dt-novel-form-grid' },
          NOVEL_BUDGET_FIELDS.map((field) => h(EditorField, {
            key: field.key,
            label: t(field.label),
            value: budgets?.[field.key] ?? '',
            type: 'number',
            min: 1,
            disabled: budgets === null,
            onChange: (value) => setBudgetField(field.key, value),
          }))),
        h('p', { className: 'dt-hint' }, t('novel.edit.budgetsHint'))),
      h('div', { className: 'dt-novel-form-section' },
        h('h4', null, t('novel.form.writerMode')),
        h('div', { className: 'dt-novel-form-grid' },
          h('div', { className: 'dt-field' },
            h('span', { className: 'dt-label' }, t('novel.form.writerMode')),
            h('div', { className: 'dt-segmented', role: 'group', 'aria-label': t('novel.form.writerMode') },
              [
                { value: 'inline', label: 'novel.form.writerMode.inline' },
                { value: 'subagent', label: 'novel.form.writerMode.subagent' },
              ].map((option) => h('button', {
                key: option.value,
                type: 'button',
                className: writerMode === option.value ? 'dt-segmented-active' : '',
                'aria-pressed': writerMode === option.value,
                disabled: detail === null,
                onClick: () => setWriterMode(option.value),
              }, t(option.label)))))),
        h('p', { className: 'dt-hint' }, t('novel.form.writerMode.hint')),
        h('p', { className: 'dt-hint' }, t('novel.edit.writerModeHint'))),
      error ? h('p', { className: 'dt-error' }, error) : null,
      notice ? h('p', { className: 'dt-muted' }, notice) : null)
    }

    function formatWorkbenchTime(value) {
      const date = new Date(value)
      return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString()
    }

    // 世界书方案字段值（string|number|boolean|null|string[]）的展示形态：
    // 数组按行 join，null 显式可见（可空字段有「跟随全局」语义），标量 String。
    function formatWorldPlanValue(value) {
      if (Array.isArray(value)) return value.join('\n')
      if (value === null) return 'null'
      if (value === undefined) return ''
      return String(value)
    }

    // 工作台方案卡片（提案 0013 P2；世界书面板化同构扩展）：pending 可批准/
    // 拒绝，已决定的显示状态；展开即 diff——卡方案逐字段，世界书方案按条目
    // 分组（#uid + 动作 + 逐字段 当前 → 改为，note 灰字）。
    function WorkbenchPlanCard({ plan, busy, open, onToggle, onDecide }) {
      const t = useTranslate()
      const isWorld = plan.kind === 'world'
      const changes = Array.isArray(plan.changes) ? plan.changes : []
      const entries = Array.isArray(plan.entries) ? plan.entries : []
      const meta = [isWorld
        ? t('workbench.worldMeta', { world: plan.world }) + (plan.op === 'create' ? ` · ${t('workbench.world.newBook')}` : '')
        : plan.character, plan.id]
      if (plan.appliedAt) meta.push(t('workbench.appliedAt', { time: formatWorkbenchTime(plan.appliedAt) }))
      else if (plan.decidedAt) meta.push(t('workbench.decidedAt', { time: formatWorkbenchTime(plan.decidedAt) }))
      else meta.push(formatWorkbenchTime(plan.createdAt))
      const renderFieldChange = (change, key) => h('div', { key, className: 'dt-workbench-change' },
        h('div', { className: 'dt-workbench-change-field' }, change.field),
        h('div', { className: 'dt-workbench-change-values' },
          change.currentValue !== undefined ? h('span', { className: 'dt-workbench-label' }, t('workbench.current')) : null,
          change.currentValue !== undefined
            ? h('pre', { className: 'dt-workbench-old' },
              // 数组值（tags/alternateGreetings/worldbook key 列表）按行 join 展示，避免压成一行
              Array.isArray(change.currentValue) ? change.currentValue.join('\n') : (change.currentValue || ''))
            : null,
          h('span', { className: 'dt-workbench-label' }, t('workbench.new')),
          h('pre', { className: 'dt-workbench-new' },
            Array.isArray(change.newValue) ? change.newValue.join('\n') : formatWorldPlanValue(change.newValue))),
        change.note ? h('p', { className: 'dt-workbench-note' }, change.note) : null)
      return h('div', { className: `dt-workbench-plan${plan.status === 'pending' ? '' : ' dt-workbench-done'}` },
        h('div', { className: 'dt-workbench-plan-head' },
          h('button', {
            type: 'button',
            className: 'dt-workbench-plan-title',
            onClick: onToggle,
            title: open ? t('workbench.hideDiff') : t('workbench.showDiff'),
          },
            h('span', { className: 'dt-workbench-caret' }, open ? '▾' : '▸'),
            h('span', null, plan.title || plan.id)),
          h('span', { className: `dt-workbench-status dt-workbench-status-${plan.status}` }, t(`workbench.status.${plan.status}`)),
          plan.status === 'pending'
            ? h('span', { className: 'dt-workbench-actions' },
                h(Button, { size: 'sm', variant: 'primary', disabled: busy, onClick: () => onDecide(plan, true) }, t('workbench.approve')),
                h(Button, { size: 'sm', variant: 'ghost', disabled: busy, onClick: () => onDecide(plan, false) }, t('workbench.reject')))
            : null),
        h('div', { className: 'dt-workbench-meta' }, meta.join(' · ')),
        open ? h('div', { className: 'dt-workbench-diff' },
          isWorld
            ? entries.map((entry, index) => h('div', { key: index, className: 'dt-workbench-entry' },
              h('div', { className: 'dt-workbench-entry-head' },
                h('span', { className: 'dt-workbench-entry-uid' }, `#${entry.uid}`),
                h('span', { className: `dt-workbench-entry-action dt-workbench-entry-action-${entry.action}` }, t(`workbench.world.${entry.action}`))),
              entry.fields.map((change, fieldIndex) => renderFieldChange(change, fieldIndex)),
              entry.note ? h('p', { className: 'dt-workbench-note' }, entry.note) : null))
            : changes.map((change, index) => renderFieldChange(change, index))) : null)
    }

    // 试写预览（D-4 生成不入楼，决策 2026-10-11-preview-generation.md）：POST
    // preview——服务端以真实装配 + 单次 LLM 生成，但零副作用（不落楼/无 MVU 结算/
    // 五相位 hook 不跑/无事件）。客户端单请求同步等待（30-60s 量级，fetch 不设短
    // 超时），取消走 AbortController 断开 fetch（服务端透传 signal 给 llm.stream）。
    function WorkbenchPreviewBand() {
      const state = useTavernStore()
      const t = useTranslate()
      const [character, setCharacter] = useState('')
      const [chatId, setChatId] = useState('')
      const [userText, setUserText] = useState('')
      const [running, setRunning] = useState(false)
      const [result, setResult] = useState(null)
      const [error, setError] = useState('')
      const [cancelled, setCancelled] = useState(false)
      const abortRef = useRef(null)
      const chats = character ? (state.chatLists[character] || []) : []
      useEffect(() => {
        setChatId('')
        if (character) void loadChatList(character).catch(() => {})
      }, [character])
      const cancel = () => { abortRef.current?.abort() }
      const run = () => {
        if (running || !character || !chatId || userText.trim() === '') return
        setRunning(true)
        setError('')
        setResult(null)
        setCancelled(false)
        const controller = new AbortController()
        abortRef.current = controller
        void api('preview', {
          method: 'POST',
          headers: jsonHeaders(),
          body: JSON.stringify({ character, chatId, userText }),
          signal: controller.signal,
        })
          .then((outcome) => { setResult(outcome); return outcome })
          .catch((cause) => {
            if (controller.signal.aborted) setCancelled(true)
            else setError(cause instanceof Error ? cause.message : String(cause))
          })
          .finally(() => { setRunning(false); abortRef.current = null })
      }
      const usageLine = result
        ? (result.usage
          ? t('workbench.preview.usage', {
            provider: result.provider || '?',
            model: result.model || '?',
            input: result.usage.inputTokens ?? '?',
            output: result.usage.outputTokens ?? '?',
          })
          : t('workbench.preview.modelLine', { provider: result.provider || '?', model: result.model || '?' }))
        : ''
      return h('section', { className: 'dt-settings-band' },
        h('h3', null, t('workbench.preview.title')),
        h('p', { className: 'dt-hint' }, t('workbench.preview.hint')),
        h('div', { className: 'dt-editor-actions' },
          h(SettingSelect, {
            label: t('settings.character'),
            value: character,
            options: state.bootstrap.characters || [],
            empty: t('workbench.preview.characterEmpty'),
            onChange: (value) => setCharacter(value || ''),
          }),
          h(SettingSelect, {
            label: t('workbench.preview.chat'),
            value: chatId,
            options: chats,
            empty: chats.length === 0 ? t('workbench.preview.chatEmpty') : t('workbench.preview.chatPick'),
            onChange: (value) => setChatId(value || ''),
          })),
        h(EditorField, {
          label: t('workbench.preview.userText'),
          value: userText,
          multiline: true,
          placeholder: t('workbench.preview.placeholder'),
          disabled: running,
          onChange: setUserText,
        }),
        h('div', { className: 'dt-imports' },
          h(Button, {
            size: 'sm',
            variant: 'primary',
            icon: h(IconSendOutline16),
            disabled: running || !character || !chatId || userText.trim() === '',
            onClick: run,
          }, running ? t('workbench.preview.running') : t('workbench.preview.run')),
          running ? h(Button, {
            size: 'sm',
            variant: 'ghost',
            icon: h(IconStopFill16),
            onClick: cancel,
          }, t('workbench.preview.cancel')) : null),
        result ? h(React.Fragment, null,
          h('p', { className: 'dt-hint' }, usageLine),
          h('pre', { style: { whiteSpace: 'pre-wrap', wordBreak: 'break-word', margin: '4px 0 0', fontSize: '13px' } }, result.text)) : null,
        cancelled ? h('p', { className: 'dt-hint' }, t('workbench.preview.cancelled')) : null,
        error ? h('p', { className: 'dt-error' }, error) : null)
    }

    function PanelWorkbench() {
      const t = useTranslate()
      const [plans, setPlans] = useState(null)
      const [error, setError] = useState('')
      const [busyId, setBusyId] = useState('')
      const [openId, setOpenId] = useState('')
      const reload = () => loadWorkbenchPlans('all')
        .then((result) => { setPlans(Array.isArray(result.plans) ? result.plans : []); setError(''); return result })
        .catch((cause) => {
          setError(cause instanceof Error ? cause.message : String(cause))
          return null
        })
      useEffect(() => { void reload() }, [])
      const decide = (plan, approve) => {
        if (busyId !== '') return
        setBusyId(plan.id)
        setError('')
        void decideWorkbenchPlan(plan.id, approve)
          .then(() => {
            // 批准会写入资产（角色卡/世界书/预设）：立即重取 bootstrap，角色卡
            // 分区与侧栏不必等下一次水位轮询就同步到新内容。
            if (approve === true) void refreshBootstrap().catch(() => {})
            return reload()
          })
          .catch((cause) => setError(cause instanceof Error ? cause.message : String(cause)))
          .finally(() => setBusyId(''))
      }
      return h(React.Fragment, null,
        h('section', { className: 'dt-settings-band' },
          h('p', { className: 'dt-hint' }, t('workbench.hint')),
          h('div', { className: 'dt-imports' },
            h(Button, {
              size: 'sm',
              variant: 'ghost',
              icon: h(IconRefreshOutline16),
              onClick: () => { setError(''); void reload() },
            }, t('workbench.refresh')))),
        h('section', { className: 'dt-settings-band' },
          error ? h('p', { className: 'dt-error' }, error) : null,
          plans === null
            ? h('p', { className: 'dt-muted' }, t('nav.loading'))
            : plans.length === 0
              ? h('p', { className: 'dt-muted' }, t('workbench.empty'))
              : h('div', { className: 'dt-workbench-list' },
                plans.map((plan) => h(WorkbenchPlanCard, {
                  key: plan.id,
                  plan,
                  busy: busyId === plan.id,
                  open: openId === plan.id,
                  onToggle: () => setOpenId(openId === plan.id ? '' : plan.id),
                  onDecide: decide,
                })))),
        h(WorkbenchPreviewBand))
    }

    function PanelNovels({ ctx }) {
      const state = useTavernStore()
      const t = useTranslate()
      const [novels, setNovels] = useState(null)
      const [error, setError] = useState('')
      const [selected, setSelected] = useState('')
      const [creating, setCreating] = useState(false)
      const [editing, setEditing] = useState(null)
      const capability = state.bootstrap.agentNovel || { available: false, missing: [], reasons: [] }
      const unavailableReason = capability.reasons?.length ? capability.reasons.join(' ')
        : capability.missing?.length ? capability.missing.join(', ') : ''
      const reload = () => fetchNovelList()
        .then((list) => { setNovels(list); setError(''); return list })
        .catch((cause) => { setError(cause instanceof Error ? cause.message : String(cause)); return null })
      useEffect(() => { void reload() }, [])
      if (selected !== '') {
        return h(NovelDetail, {
          ctx,
          novelId: selected,
          onBack: () => setSelected(''),
          onChanged: () => { void reload() },
        })
      }
      return h(React.Fragment, null,
        h('section', { className: 'dt-settings-band' },
          h('div', { className: 'dt-imports' },
            h(Button, {
              size: 'sm',
              variant: 'primary',
              icon: h(IconPlusOutline16),
              disabled: capability.available !== true,
              title: capability.available !== true && unavailableReason !== ''
                ? t('novel.createUnavailable', { reason: unavailableReason })
                : undefined,
              onClick: () => setCreating(true),
            }, t('novel.create')),
            h(Button, {
              size: 'sm',
              variant: 'ghost',
              icon: h(IconRefreshOutline16),
              onClick: () => { setError(''); void reload() },
            }, t('novel.refresh'))),
          capability.available !== true
            ? h('p', { className: 'dt-hint' }, t('novel.createUnavailable', { reason: unavailableReason || '—' }))
            : null),
        h('section', { className: 'dt-settings-band' },
          novels === null
            ? h('p', { className: 'dt-muted' }, t('nav.loading'))
            : novels.length === 0
              ? h('p', { className: 'dt-muted' }, t('novel.empty'))
              : h('div', { className: 'dt-novel-list' }, novels.map((novel) => h(NovelCard, {
                key: novel.novelId,
                ctx,
                novel,
                t,
                onDetail: () => setSelected(novel.novelId),
                onEdit: () => setEditing(novel),
                onChanged: reload,
              }))),
          error ? h('p', { className: 'dt-error' }, error) : null),
        creating ? h(NovelCreateForm, {
          onClose: () => setCreating(false),
          onCreated: (created) => {
            setCreating(false)
            void reload().then((list) => {
              if (list !== null && created?.novelId) setSelected(created.novelId)
            })
          },
        }) : null,
        editing ? h(NovelEditForm, {
          novel: editing,
          onClose: () => setEditing(null),
          onSaved: () => { setEditing(null); void reload() },
        }) : null)
    }

    // Mod 管理分区（提案 0015 §3.5 P1）：列表数据来自 bootstrap.mods 投影，
    // 全局开关读 bootstrap.state.modsEnabled；写操作走 /mods 管理路由并重取
    // bootstrap（patchState 同款动作-刷新闭环；state.json 不进 store-revision
    // 水位，自动轮询不覆盖这条路径）。
    function PanelMods() {
      const state = useTavernStore()
      const t = useTranslate()
      const [error, setError] = useState('')
      const [pending, setPending] = useState('')
      const [confirming, setConfirming] = useState(null)
      const [installUrl, setInstallUrl] = useState('')
      const [installForce, setInstallForce] = useState(false)
      const [installStatus, setInstallStatus] = useState('')
      const run = (id, promise) => {
        setPending(id)
        setError('')
        void promise.then(refreshBootstrap).catch((cause) => setError(cause instanceof Error ? cause.message : String(cause)))
          .finally(() => setPending(''))
      }
      const mods = state.bootstrap.mods || []
      const available = state.bootstrap.modsAvailable !== false
      const globalEnabled = state.bootstrap.state.modsEnabled === true
      const setGlobalEnabled = (enabled) => run('global', api('mods/state', {
        method: 'POST',
        headers: jsonHeaders(),
        body: JSON.stringify({ globalEnabled: enabled === true }),
      }))
      const enableMod = (mod) => run(mod.id, api(`mods/${encodeURIComponent(mod.id)}/enable`, {
        method: 'POST',
        headers: jsonHeaders(),
        body: '{}',
      }))
      const disableMod = (mod) => run(mod.id, api(`mods/${encodeURIComponent(mod.id)}/disable`, {
        method: 'POST',
        headers: jsonHeaders(),
        body: '{}',
      }))
      const reloadMod = (mod) => run(mod.id, api(`mods/${encodeURIComponent(mod.id)}/reload`, {
        method: 'POST',
        headers: jsonHeaders(),
        body: '{}',
      }))
      // git 安装（提案 0015 §4 P2）：GitHub URL / owner/repo，可选 #ref；进度与
      // 结果就地反馈（安装是长操作——clone 可能几十秒，按钮锁死防重复提交）。
      const installFromGit = () => {
        const url = installUrl.trim()
        if (url === '' || busy('install')) return
        setInstallStatus(t('mods.install.installing'))
        void api('mods/install', {
          method: 'POST',
          headers: jsonHeaders(),
          body: JSON.stringify({ url, ...(installForce ? { force: true } : {}) }),
        })
          .then((result) => {
            setInstallStatus(t('mods.install.done', { id: result.installed?.modId ?? '' }))
            setInstallUrl('')
            return refreshBootstrap()
          })
          .catch((cause) => setInstallStatus(t('mods.install.failed', { error: cause instanceof Error ? cause.message : String(cause) })))
      }
      const busy = (id) => pending === id
      const surfaceRows = (mod) => [
        { label: t('mods.confirmHooks'), entries: mod.surfaces?.hooks || [] },
        { label: t('mods.confirmTools'), entries: mod.surfaces?.tools || [] },
        { label: t('mods.confirmHttp'), entries: mod.surfaces?.http || [] },
      ]
      return h(React.Fragment, null,
        h('section', { className: 'dt-settings-band' },
          !available
            ? h('p', { className: 'dt-hint' }, t('mods.unavailable'))
            : h(React.Fragment, null,
              h('p', { className: 'dt-hint' }, t('mods.globalHint')),
              h('div', { className: 'dt-imports' },
                h('label', { className: 'dt-toggle' },
                  h('input', {
                    type: 'checkbox',
                    disabled: busy('global'),
                    checked: globalEnabled,
                    onChange: (event) => setGlobalEnabled(event.target.checked),
                  }),
                  h('span', null, t('mods.globalToggle')))))),
        h('section', { className: 'dt-settings-band' },
          h('h3', null, t('mods.install.title')),
          h('p', { className: 'dt-hint' }, t('mods.install.hint')),
          h('div', { className: 'dt-mod-install' },
            h('input', {
              type: 'text',
              value: installUrl,
              placeholder: t('mods.install.placeholder'),
              disabled: busy('install'),
              onChange: (event) => setInstallUrl(event.target.value),
              onKeyDown: (event) => { if (event.key === 'Enter') installFromGit() },
            }),
            h(Button, { size: 'sm', variant: 'outline', disabled: busy('install') || installUrl.trim() === '', onClick: installFromGit },
              busy('install') ? t('mods.install.installing') : t('mods.install.button')),
            h('label', { className: 'dt-toggle' },
              h('input', {
                type: 'checkbox',
                checked: installForce,
                onChange: (event) => setInstallForce(event.target.checked),
              }),
              h('span', null, t('mods.install.force')))),
          installStatus ? h('p', { className: 'dt-hint' }, installStatus) : null),
        h('section', { className: 'dt-settings-band' },
          mods.length === 0
            ? h('p', { className: 'dt-muted' }, t('mods.empty', { path: 'soulmojito/mods/' }))
            : h('div', { className: 'dt-mod-list' }, mods.map((mod) => h('article', { key: mod.id, className: 'dt-mod-row' },
              h('div', { className: 'dt-mod-row-head' },
                h('strong', null, mod.name),
                h('span', { className: 'dt-mod-meta' }, `v${mod.version} · ${mod.author}`),
                h(Pill, { active: mod.status === 'loaded' }, t(`mods.status.${mod.status}`))),
              h('p', { className: 'dt-mod-desc' }, mod.description),
              h('div', { className: 'dt-mod-cap' },
                h('span', { className: 'dt-mod-cap-label' }, t('mods.confirmCapabilities')),
                (mod.capabilities || []).length === 0
                  ? h('span', null, t('mods.capability.none'))
                  : mod.capabilities.map((capability) => h(Pill, { key: capability }, t(`mods.capability.${capability}`))),
                // 声明式按钮（A-1a）：能力 Pill 区披露按钮数（按钮渲染进宿主 UI）。
                (mod.buttons || []).length > 0
                  ? h(Pill, { key: 'buttons' }, t('mods.buttonsPill', { count: mod.buttons.length }))
                  : null),
              mod.error ? h('p', { className: 'dt-error' }, mod.error) : null,
              h('div', { className: 'dt-mod-actions' },
                h('span', { className: 'dt-mod-meta' }, t('mods.auditCount', { count: mod.auditCount ?? 0 })),
                mod.status === 'loaded'
                  ? h(React.Fragment, null,
                    mod.panel
                      ? h(Button, { size: 'sm', variant: 'ghost', onClick: () => update({ panelSection: `mod:${mod.id}`, panelOpen: true }) }, t('mods.openPanel'))
                      : null,
                    h(Button, { size: 'sm', variant: 'outline', disabled: busy(mod.id), onClick: () => disableMod(mod) }, busy(mod.id) ? t('mods.busy') : t('mods.disable')),
                    h(Button, { size: 'sm', variant: 'ghost', icon: h(IconRefreshOutline16), disabled: busy(mod.id), onClick: () => reloadMod(mod) }, t('mods.reload')))
                  : mod.status === 'disabled'
                    ? h(Button, { size: 'sm', variant: 'outline', disabled: busy(mod.id) || !available, onClick: () => setConfirming(mod) }, busy(mod.id) ? t('mods.busy') : t('mods.enable'))
                    : null)))),
          error ? h('p', { className: 'dt-error' }, error) : null),
        confirming
          ? h(Modal, {
            open: true,
            onClose: () => setConfirming(null),
            title: t('mods.confirmTitle', { name: confirming.name }),
            closeLabel: t('panel.close'),
          },
            h('div', { className: 'dt-settings-band dt-mod-confirm' },
              h('p', { className: 'dt-hint' }, t('mods.confirmBody')),
              h('div', { className: 'dt-mod-cap' },
                h('span', { className: 'dt-mod-cap-label' }, t('mods.confirmCapabilities')),
                (confirming.capabilities || []).length === 0
                  ? h('span', null, t('mods.capability.none'))
                  : confirming.capabilities.map((capability) => h(Pill, { key: capability }, t(`mods.capability.${capability}`))),
                // 声明按钮（A-1a 知情同意面）：按钮渲染进宿主 UI（面板 chips + 聊天
                // 按钮行），点击会执行该 Mod 的 handler——数量与名单在此披露。
                (confirming.buttons || []).length > 0
                  ? h(Pill, { key: 'buttons' }, t('mods.buttonsPill', { count: confirming.buttons.length }))
                  : null),
              (confirming.buttons || []).length > 0 ? h('div', { className: 'dt-mod-cap' },
                h('span', { className: 'dt-mod-cap-label' }, t('mods.confirmButtons')),
                confirming.buttons.map((name, index) => h(Pill, { key: `${name}:${index}` }, name))) : null,
              // §3.5：确认弹层展示声明的 hooks/tools/http 注册面。disabled mod
              // 展示 manifest 声明（作者自查），loaded 展示实际注册名单。
              h('p', { className: 'dt-hint' }, t('mods.confirmSurfacesHint')),
              surfaceRows(confirming).map(({ label, entries }) => h('div', { key: label, className: 'dt-mod-cap' },
                h('span', { className: 'dt-mod-cap-label' }, label),
                entries.length === 0
                  ? h('span', null, t('mods.confirmSurfacesNone'))
                  : entries.map((entry, index) => h(Pill, { key: `${entry}:${index}` }, entry)))),
              h('div', { className: 'dt-imports' },
                h(Button, { variant: 'outline', onClick: () => setConfirming(null) }, t('panel.cancel')),
                h(Button, {
                  variant: 'primary',
                  onClick: () => {
                    const target = confirming
                    setConfirming(null)
                    enableMod(target)
                  },
                }, t('mods.enable')))))
          : null)
    }

    // 关于分区：纯静态信息面——头部品牌面是 logo 组件（与面板品牌块同源）加
    // 正式写法 DSH-SoulMojito（旧的小写 dsh-soulmojito 只是目录名习惯），版本
